  var C5 = ops([['P1', '', 'R(x)a', '', 'W(x)c', '', ''], ['P2', 'W(x)a', '', 'W(x)b', '', '', ''], ['P3', '', '', '', '', 'R(x)b', 'R(x)c'], ['P4', '', '', '', '', 'R(x)c', 'R(x)b']]);
