  var C7 = ops([['P1', 'W(x)a', '', '', 'R(x)b'], ['P2', '', 'R(x)a', 'W(x)b', ''], ['P3', '', 'R(x)a', '', 'R(x)b'], ['P4', '', '', 'R(x)a', 'R(x)b']]);
  var C8 = ops([['P1', 'W(x)a', '', '', ''], ['P2', '', 'W(x)b', 'W(x)c', ''], ['P3', 'R(x)a', 'R(x)b', '', 'R(x)c'], ['P4', '', 'R(x)b', '', 'R(x)c']]);
